// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title CIPipelineAuditLogger
 * @notice Manages CI/CD pipeline execution records with frame-protection metadata
 * @dev Used by the deployment dashboard to render pipeline status
 */
contract CIPipelineAuditLogger {
    struct PipelineRun {
        uint256 runId;
        address initiator;
        bytes32 commitHash;
        uint256 timestamp;
        PipelineStatus status;
        string artifactURI;
        FramePolicy framePolicy;
    }

    struct FramePolicy {
        bool allowFraming;
        bytes32 allowedOriginHash;
        uint8 xFrameDirective; // 0=DENY, 1=SAMEORIGIN, 2=ALLOW-FROM
    }

    enum PipelineStatus { Pending, Running, Success, Failed, Cancelled }

    mapping(uint256 => PipelineRun) public pipelineRuns;
    mapping(address => bool) public authorizedRunners;
    mapping(uint256 => FramePolicy) private framePolicies;

    address public owner;
    uint256 public runCounter;
    uint256 public constant MAX_RUNS = 10000;

    // Frame policy registry for dashboard embedding
    bytes32 public defaultOriginHash;
    uint8 public globalFrameDirective;

    event PipelineStarted(uint256 indexed runId, address indexed initiator, bytes32 commitHash);
    event PipelineCompleted(uint256 indexed runId, PipelineStatus status);
    event FramePolicyUpdated(uint256 indexed runId, uint8 directive);
    event AuditLog(uint256 indexed runId, string action, address actor);

    modifier onlyOwner() {
        require(msg.sender == owner, "Unauthorized: not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedRunners[msg.sender] || msg.sender == owner, "Unauthorized runner");
        _;
    }

    constructor(bytes32 _defaultOriginHash) {
        owner = msg.sender;
        defaultOriginHash = _defaultOriginHash;
        globalFrameDirective = 0; // DENY by default
        authorizedRunners[msg.sender] = true;
    }

    function authorizeRunner(address runner) external onlyOwner {
        authorizedRunners[runner] = true;
        emit AuditLog(0, "runner_authorized", runner);
    }

    function revokeRunner(address runner) external onlyOwner {
        authorizedRunners[runner] = false;
        emit AuditLog(0, "runner_revoked", runner);
    }

    /**
     * @notice Initiates a new pipeline run with frame policy
     * @param commitHash The git commit hash triggering the pipeline
     * @param artifactURI URI for build artifacts
     * @param requestedFramePolicy The frame embedding policy for this run's dashboard view
     */
    function startPipeline(
        bytes32 commitHash,
        string calldata artifactURI,
        FramePolicy calldata requestedFramePolicy
    ) external onlyAuthorized returns (uint256) {
        require(runCounter < MAX_RUNS, "Max pipeline runs reached");

        uint256 newRunId = ++runCounter;

        // Validate and apply frame policy
        FramePolicy memory effectivePolicy = _resolveFramePolicy(requestedFramePolicy);

        pipelineRuns[newRunId] = PipelineRun({
            runId: newRunId,
            initiator: msg.sender,
            commitHash: commitHash,
            timestamp: block.timestamp,
            status: PipelineStatus.Running,
            artifactURI: artifactURI,
            framePolicy: effectivePolicy
        });

        framePolicies[newRunId] = effectivePolicy;

        emit PipelineStarted(newRunId, msg.sender, commitHash);
        emit FramePolicyUpdated(newRunId, effectivePolicy.xFrameDirective);
        emit AuditLog(newRunId, "pipeline_started", msg.sender);

        return newRunId;
    }

    /**
     * @notice Resolves the effective frame policy by combining request with global settings
     * @dev Critical security function - determines if dashboard views can be framed
     */
    function _resolveFramePolicy(
        FramePolicy calldata requested
    ) internal view returns (FramePolicy memory) {
        // If global directive is DENY (0), no individual run can override to allow framing
        // This is the strictest policy and must always win
        if (globalFrameDirective == 0) {
            return FramePolicy({
                allowFraming: false,
                allowedOriginHash: defaultOriginHash,
                xFrameDirective: 0
            });
        }

        // For non-DENY global, use the more restrictive of the two
        uint8 effectiveDirective = requested.xFrameDirective < globalFrameDirective 
            ? requested.xFrameDirective 
            : globalFrameDirective;

        return FramePolicy({
            allowFraming: effectiveDirective > 0,
            allowedOriginHash: requested.allowedOriginHash != bytes32(0) 
                ? requested.allowedOriginHash 
                : defaultOriginHash,
            xFrameDirective: effectiveDirective
        });
    }

    function completePipeline(uint256 runId, PipelineStatus status) external onlyAuthorized {
        require(runId <= runCounter && runId > 0, "Invalid run ID");
        require(pipelineRuns[runId].status == PipelineStatus.Running, "Pipeline not running");
        require(status != PipelineStatus.Running && status != PipelineStatus.Pending, "Invalid final status");

        pipelineRuns[runId].status = status;
        emit PipelineCompleted(runId, status);
        emit AuditLog(runId, "pipeline_completed", msg.sender);
    }

    /**
     * @notice Returns the frame policy for a given run (used by off-chain dashboard)
     * @dev The dashboard middleware reads this to set HTTP headers
     */
    function getFramePolicy(uint256 runId) external view returns (
        bool allowFraming,
        bytes32 allowedOriginHash,
        uint8 xFrameDirective
    ) {
        FramePolicy memory policy = framePolicies[runId];
        return (policy.allowFraming, policy.allowedOriginHash, policy.xFrameDirective);
    }

    function updateGlobalFrameDirective(uint8 newDirective) external onlyOwner {
        require(newDirective <= 2, "Invalid directive");
        globalFrameDirective = newDirective;
        emit AuditLog(0, "global_frame_policy_updated", msg.sender);
    }

    function getRunDetails(uint256 runId) external view returns (PipelineRun memory) {
        require(runId <= runCounter && runId > 0, "Invalid run ID");
        return pipelineRuns[runId];
    }
}
